/**
 * matcha — inject-rules.js
 * Lifecycle hooks for Claude Code and Codex.
 * Injects matcha philosophy before tasks.
 * Post-task snarky suggestions are AI-generated by the agent
 * (instructed via SKILL.md, not hardcoded here).
 */

import { getMatchaInstructions, getProjectConstraints } from "./matcha-instructions.js";
import { getIntensity } from "./planning-gate.js";
import { readFileSync, existsSync } from "fs";
import { join } from "path";
import { getWorkspaceRoot } from "./workspace-root.js";
import { getPlanResumeHint } from "./plan-compact.js";

// ─── Hook handlers ─────────────────────────────────────────────────────────────

export async function preTask(event, context) {
  const cwd = event?.cwd || process.cwd();
  if (getIntensity(cwd) === "off") {
    return {
      metadata: { convention: "matcha", enabled: false, event: event?.type },
    };
  }

  const instructions = getMatchaInstructions();
  const projectConstraints = getProjectConstraints();

  // Self-enforcing resume hint (issue #3 P2): surface the live plan as a
  // one-liner so compaction/session resume never depends on model recall.
  let planHint = "";
  try {
    const root = getWorkspaceRoot(cwd);
    const planPath = join(root, ".agents", "plan", "current.md");
    if (existsSync(planPath)) {
      const hint = getPlanResumeHint(readFileSync(planPath, "utf-8"));
      if (hint) planHint = `\n### 📋 Session Resume\n${hint} — read \`.agents/plan/current.md\` at task start to resume continuity.\n`;
    }
  } catch {}

  const projectSection = projectConstraints
    ? `
### 📋 Project Constraints (from MATCHA_PROJECT.md)
The following project-specific rules are ACTIVE. Follow them strictly:

${projectConstraints}
`
    : "";

  return {
    system_suffix: `
---
## Active Convention: matcha 🍵

You are operating under the matcha engineering philosophy.
Full ruleset injected below — follow it for every action in this session.

### 🔴 CRITICAL PLANNING GATE (ENFORCED BY HOOK)
You are BLOCKED from modifying files or running commands until you create/update the Intent Discovery plan in \`.agents/plan/current.md\`.
The hook will automatically allow execution once this file contains a valid Intent Discovery plan:
\`\`\`markdown
---
title: <task>
date: <date>
type: plan
status: active
---
# 🍵 Intent Discovery
- **Problem:** <problem description>
- **Goals:** <goals>
- **Success Criteria:** <success criteria>
\`\`\`
For every new task or major request, you MUST overwrite/update \`.agents/plan/current.md\` with the current task's details.

### Persistence of Intensity
If the user runs \`/matcha observe|enforce|audit\`, persist the change by writing \`{"intensity": "observe|enforce|audit"}\` to \`.agents/matcha-state.json\`.

At the END of every task response, include 3 matcha suggestions (match the user's conversation language, casual, direct, slightly sarcastic tone).
${planHint}${projectSection}
${instructions}
---
`,
    metadata: { convention: "matcha", version: "2.5.44", event: event.type },
  };
}

// Default export for backward compat
export default async function handler(event, context) {
  if (event.type === "before:task" || event.type === "before:tool_use") {
    return preTask(event, context);
  }
  return null;
}
